# this_file: src/fontlab_instamix/launchers.py
"""Menu scripts in ``Scripts/Instamix``: list installs, uninstall one install.

``Uninstall <id>.py`` belongs to that id's ledger record. The shared
``List Extensions.py`` is rewritten on every install and removed with the
last record. Both import :mod:`fontlab_instamix`, so the package must stay
in site-packages.
"""

from __future__ import annotations

from pathlib import Path

FOLDER = "Scripts/Instamix"
LIST = "List Extensions.py"
TEMPLATE = (
    "#FLM: {title}\n"
    "# Generated by fontlab-instamix; replaced on every install.\n"
    "from fontlab_instamix import launch\n"
    "launch.{call}\n"
)


def text(title: str, call: str) -> str:
    """Launcher source for menu *title* that runs ``launch.<call>``."""
    return TEMPLATE.format(title=title, call=call)


def folder(data: Path) -> Path:
    return Path(data) / FOLDER


def uninstaller_path(data: Path, ext_id: str) -> Path:
    return folder(data) / f"Uninstall {ext_id}.py"


def write_uninstaller(data: Path, ext_id: str) -> list[Path]:
    """Write ``Uninstall <id>.py`` and return its path (the shared folder is not owned)."""
    folder(data).mkdir(parents=True, exist_ok=True)
    path = uninstaller_path(data, ext_id)
    path.write_text(text(f"Uninstall {ext_id}", f"uninstall({ext_id!r})"), encoding="utf-8")
    return [path]


def write_list(data: Path) -> Path:
    """(Re)write the shared ``List Extensions.py`` launcher."""
    folder(data).mkdir(parents=True, exist_ok=True)
    path = folder(data) / LIST
    path.write_text(text("List Extensions", "list_extensions()"), encoding="utf-8")
    return path


def remove_list(data: Path) -> None:
    """Remove the shared launcher if unchanged, then the folder if empty."""
    path = folder(data) / LIST
    if path.is_file() and not path.is_symlink() and path.read_text(encoding="utf-8") == text(
        "List Extensions", "list_extensions()"
    ):
        path.unlink()
    try:
        folder(data).rmdir()
    except OSError:
        pass
